        .create_radial_gradient(c, s * 0.18, 0.0, c, s * 0.18, s * 0.6)
        .unwrap();
    let _ = glo.add_color_stop(0.0, "rgba(207,244,255,0.15)");
    let _ = glo.add_color_stop(0.55, "rgba(207,244,255,0)");
    ctx.set_fill_style_canvas_gradient(&glo);
    ctx.begin_path();
