            if x == 0.0 {
                ctx.move_to(-2.0, y);
            } else {
                ctx.line_to(x, y);
            }
            x += step;
        }
    };
    ctx.set_stroke_style_str("rgba(191,239,248,0.30)");
    ctx.set_line_width(1.4_f64.max(s * 0.030));
    crest_path(ctx);
    ctx.stroke();
    ctx.set_stroke_style_str("rgba(234,252,255,0.85)");
    ctx.set_line_width(0.7_f64.max(s * 0.012));
    crest_path(ctx);
    ctx.stroke();
}

